INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Divisionsmethode nur für mathematische Probleme gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Algorithmen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip liegt der Divisionsmethode zugrunde?', 3, '[{"text": "Teilen und Herrschen", "correct": true, "because": "Problem aufteilen"}, {"text": "Schrittweise Verfeinerung", "correct": false, "because": "Andere Methode"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Nicht zielführend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst die Divisionsmethode?', 5, '[{"text": "Teilen", "correct": true, "because": "Problem zerlegen"}, {"text": "Herrschen", "correct": true, "because": "Teillösungen kombinieren"}, {"text": "Wiederholen", "correct": false, "because": "Iterativ anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Divisionsmethode zerlegt Probleme. b) Sie ist immer linear.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft rekursiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Divisionsmethode?', 4, '[{"text": "Teilprobleme", "correct": false, "because": "Kern der Methode"}, {"text": "Rekursion", "correct": false, "because": "Häufig genutzt"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Divisionsmethode rekursiv ist?', 2, '[{"text": "Ja", "correct": true, "because": "Oft rekursiv aufgeteilt"}, {"text": "Nein", "correct": false, "because": "Rekursion üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Algorithmus nutzt die Divisionsmethode?', 3, '[{"text": "Merge Sort", "correct": true, "because": "Teilen und Zusammenführen"}, {"text": "Bubble Sort", "correct": false, "because": "Iterativ"}, {"text": "Dijkstra", "correct": false, "because": "Graphen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Divisionsmethode?', 5, '[{"text": "Effizienz", "correct": true, "because": "Kleinere Probleme"}, {"text": "Parallelisierung", "correct": true, "because": "Teilprobleme unabhängig"}, {"text": "Lineare Laufzeit", "correct": false, "because": "Oft logarithmisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Divisionsmethode teilt Probleme. b) Sie ist für kleine Datenmengen besser. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Große Daten effektiver"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Divisionsmethode?', 4, '[{"text": "Teilstrategie", "correct": false, "because": "Kern der Methode"}, {"text": "Kombination", "correct": false, "because": "Lösung zusammenführen"}, {"text": "Manuelle Eingabe", "correct": true, "because": "Algorithmisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Divisionsmethode immer rekursiv?', 2, '[{"text": "Nein", "correct": true, "because": "Kann iterativ sein"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Algorithmen basieren auf dieser Methode?', 4, '[{"text": "Quick Sort", "correct": true, "because": "Teilt Daten"}, {"text": "Binary Search", "correct": true, "because": "Hälften suchen"}, {"text": "Linear Search", "correct": false, "because": "Nicht geteilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Divisionsmethode nur für Sortieren ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Suche"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Divisionsmethode?', 3, '[{"text": "Problemzerlegung", "correct": true, "because": "Erster Schritt"}, {"text": "Zufällige Teilung", "correct": false, "because": "Strukturiert"}, {"text": "Lineare Lösung", "correct": false, "because": "Rekursiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Divisionsmethode nutzt Rekursion. b) Sie ist immer langsamer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst die Divisionsmethode effektiv?', 5, '[{"text": "Sortieren", "correct": true, "because": "Z. B. Merge Sort"}, {"text": "Suche", "correct": true, "because": "Z. B. Binary Search"}, {"text": "Graphen", "correct": false, "because": "Andere Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Divisionsmethode unwichtig?', 3, '[{"text": "Teilprobleme", "correct": false, "because": "Kern"}, {"text": "Kombination", "correct": false, "because": "Lösung"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Laufzeit der Divisionsmethode immer linear?', 3, '[{"text": "Nein", "correct": true, "because": "Oft O(n log n)"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Divisionsmethode parallele Verarbeitung fördert?', 2, '[{"text": "Ja", "correct": true, "because": "Teilprobleme unabhängig"}, {"text": "Nein", "correct": false, "because": "Parallel möglich"}]'),
